package guidedrecovery

import "strings"

var languages = []string{"en", "de", "fr", "es", "pt", "fi", "ru"}

func language(v string) string {
	for _, l := range languages {
		if v == l {
			return l
		}
	}
	return "en"
}
func tr(lang, key string) string { return translations[lang][key] }

var translations = func() map[string]map[string]string {
	out := map[string]map[string]string{}
	for _, l := range languages {
		out[l] = map[string]string{}
	}
	for _, line := range strings.Split(strings.TrimSpace(catalog), "\n") {
		fields := strings.Split(line, "|")
		if len(fields) != 8 {
			panic("recovery translation columns")
		}
		for i, l := range languages {
			out[l][fields[0]] = fields[i+1]
		}
	}
	return out
}()

